spec.code:
const full = { Version: "2012-10-17", Statement: { Effect: "Allow", Action: "*", Resource: "*" } };
const admin = { Version: "2012-10-17", Statement: { Effect: "Allow", Action: "*", Resource: "*" } };
const decide = (action: string, resource: string, context?: Record<string, string>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::777788889999:role/admin-sandbox", accountId: "777788889999" },
      action,
      resource: { arn: resource, accountId: "777788889999" },
      context,
    },
    identityPolicies: [admin],
    scps: [[full], [scp], [full]],
  }).decision;
assert.strictEqual(decide("s3:PutObject", "arn:aws:s3:::amzn-s3-demo-bucket-sandbox/datos.csv"), "Allow");

